<div class="admin-heading"><div><span>المحتوى والسيو</span><h1>إدارة المقالات</h1></div><a class="admin-btn" href="/admin/posts/create">مقال جديد</a></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>العنوان</th><th>الحالة</th><th>تاريخ النشر</th><th></th></tr></thead><tbody><?php foreach($posts as $p):?><tr><td><b><?= e($p['title']) ?></b><small>/blog/<?= e($p['slug']) ?></small></td><td><span class="status"><?= $p['status']==='published'?'منشور':'مسودة' ?></span></td><td><?= e($p['published_at'] ?: '—') ?></td><td class="actions"><a href="/admin/posts/<?= (int)$p['id'] ?>/edit">تعديل</a><form method="post" action="/admin/posts/<?= (int)$p['id'] ?>/delete" onsubmit="return confirm('حذف المقال؟')"><?= csrf_field() ?><button>حذف</button></form></td></tr><?php endforeach; ?><?php if(!$posts):?><tr><td colspan="4" class="empty">لم تتم إضافة مقالات بعد.</td></tr><?php endif; ?></tbody></table></div></section>